import {MotionTrails} from './MotionTrails.js';
export class GestureDebugOverlay {
 constructor(scene,panel,canvas,text){this.panel=panel;this.canvas=canvas;this.text=text;this.ctx=canvas.getContext?.('2d');this.trails=new MotionTrails(scene);this.trails.group.visible=false;this.frames=[];this.timer=0;this.start=null;}
 update(control,pose,dt,enabled){this.panel.hidden=!enabled;this.trails.group.visible=!!enabled;if(!enabled)return;this.timer+=dt;if(this.timer<.05)return;this.timer=0;const g=control.gestures.gesture,f=g.features,i=control.gestures.intent;if(!f||!i)return;if(this.start!==f.gestureStartTime){this.start=f.gestureStartTime;this.frames=[];}this.frames.push({time:control.clock,pose});if(this.frames.length>120)this.frames.shift();this.trails.set(this.frames);this.text.textContent=`Mean ${f.averageAngle.toFixed(1)}° · terminal ${f.terminalAngle.toFixed(1)}°\nSpeed ${f.averageSpeed.toFixed(2)} / peak ${f.peakVelocity.toFixed(2)}\nCurve ${f.curvature.toFixed(2)} · height ${f.startHeight.toFixed(2)} → ${f.endHeight.toFixed(2)}\nEffort ${i.effort.toFixed(2)} · loft ${i.loftIntent.toFixed(2)}\nContact estimate ${i.contactIntent.height.toFixed(2)} m\n${i.candidates.map(s=>s.id+' '+s.score.toFixed(2)).join(' / ')}`;if(!this.ctx)return;const c=this.ctx;c.clearRect(0,0,260,140);for(const [points,color] of [[g.samples.map(p=>({x:p.normalizedX,y:p.normalizedY})),'#ffb66b'],[g.smoothed,'#79edd2']]){c.beginPath();c.strokeStyle=color;c.lineWidth=2;points.forEach((p,n)=>n?c.lineTo(p.x*260,p.y*140):c.moveTo(p.x*260,p.y*140));c.stroke();}for(const p of [g.smoothed[0],g.smoothed.at(-1)])if(p){c.fillStyle='#d8f58e';c.beginPath();c.arc(p.x*260,p.y*140,3,0,7);c.fill();}}
}
